def _cases(*tables):
    return [pytest.param(source, args, id=name) for table in tables for name, (source, args) in table.items()]


def assert_no_backend_proves(source, *args):
    """No backend proves `source` on `args`: rejected at compile time, or the
    mock rejects the witness, halo2-base has no verifying proof and Noir's
    execution fails."""
    try:
        program = compile_kernel(source)
    except ZinniaException:
        return
    satisfied, _, _ = run_mock_layout(program, *args)
    assert not satisfied, "the mock accepts the input"
    try:
        proof = program.prove(*args, backend="halo2-base")
        assert not program.verify(proof), "halo2-base proves the input"
    except AssertionError:
        raise
    except Exception:  # noqa: BLE001  (no proof)
        pass
    if nargo_available():
        import json
        from zinnia._zinnia_core import execute_noir_circuit
        from zinnia.exec.input_parser import build_circuit_inputs

        witness = build_circuit_inputs(program.program_inputs, args)
        with pytest.raises(Exception):
            execute_noir_circuit(program._compiled_ir, json.dumps(witness), {}, json.dumps(NOIR_PARAMS))


def assert_never_wrong(source, *args):
    """NumPy's values on every backend, or no proof (Python raises, or
    Zinnia rejects the program or the input); never another value."""
    try:
        expected, _ = numpy_outputs(source, *args)
    except Exception:  # noqa: BLE001
        assert_no_backend_proves(source, *args)
        return
    try:
        program = compile_kernel(source)
    except ZinniaException:
        return
    satisfied, values, _ = run_mock_layout(program, *args)
    if satisfied:
        assert values == expected
        assert_all_backends_match_numpy(source, *args)


MATCH = _cases(*[v for k, v in sorted(globals().items()) if k.startswith("R4_") and k.endswith("_MATCH")])
RAISES = _cases(*[v for k, v in sorted(globals().items()) if k.startswith("R4_") and k.endswith("_RAISES")])
STALE_CASES = _cases(*[v for k, v in sorted(globals().items()) if k.startswith("R4_") and k.endswith("_STALE")])
SHAPES_CASES = _cases(*[v for k, v in sorted(globals().items()) if k.startswith("R4_") and k.endswith("_SHAPES")])
UNSUPPORTED = _cases(*[v for k, v in sorted(globals().items()) if k.startswith("R4_") and k.endswith("_UNSUPPORTED")])


@pytest.mark.parametrize("source, args", MATCH)
def test_the_reproducer_matches_numpy(source, args):
    assert_all_backends_match_numpy(source, *args)


@pytest.mark.parametrize("source, args", RAISES)
def test_no_backend_proves_an_input_on_which_python_raises(source, args):
    with pytest.raises(Exception):
        numpy_outputs(source, *args)
    assert_no_backend_proves(source, *args)


@pytest.mark.parametrize("source, args", STALE_CASES)
def test_reading_a_stale_array_is_rejected(source, args):
    with pytest.raises(ZinniaException, match=STALE):
        compile_kernel(source)


@pytest.mark.parametrize("source, args", SHAPES_CASES)
def test_using_a_name_bound_to_different_shapes_is_rejected(source, args):
    with pytest.raises(ZinniaException, match=SHAPES):
        compile_kernel(source)


@pytest.mark.parametrize("source, args", UNSUPPORTED)
def test_an_unsupported_reproducer_is_never_wrong(source, args):
    assert_never_wrong(source, *args)


# ── More cases per finding ───────────────────────────────────────────────

X6 = np.array([3, -1, 4, -6, 5, 9], dtype=np.int64)
INPUTS = [X6, -np.abs(X6), np.array([-3, -1, 4, -6, 5, 9], dtype=np.int64), np.arange(6, dtype=np.int64)]
H = 'def kernel(x: Integer[Array, "6"], c: Boolean):\n'

MORE = {
    # R1: a write through a name rebound in a branch reaches every array it may be.
    "R1 list append in a branch, then a base write": H + '    L = [x[::2]]\n    if c:\n        L.append(x * 1)\n    x[2] = 50\n    return L[0]\n',
    "R1 element write in a branch, then a write through the name": H + '    a = x[1:4]\n    if c:\n        a = x * 1\n        a[a > 2] = 0\n    a[0] = 77\n    return x\n',
    # R2, R3: loop targets after the loop.
    "R3 find the first negative": H + '    for j in range(6):\n        if x[j] < 0:\n            break\n    return j\n',
    "R3 find the first negative, else": H + '    for j in range(6):\n        if x[j] < 0:\n            break\n    else:\n        j = -1\n    return j\n',
    "R3 target and body variable": H + '    s = 0\n    for j in range(6):\n        s = s + x[j]\n        if s > 4:\n            break\n    return j, s\n',
    "R3 tuple target": H + '    for i, v in enumerate(x):\n        if v < 0:\n            break\n    return i, v\n',
    "R3 nested loops": H + '    for i in range(2):\n        for j in range(3):\n            if x[i + j] < 0:\n                break\n    return i, j\n',
    "R2 runtime-shaped iteration": H + '    for v in x[x > 4]:\n        pass\n    return v\n',
    # R4: return and continue in a for-else block.
    "R4 return in else": H + '    for k in range(3):\n        if x[k] > 0:\n            break\n    else:\n        return 1\n    return 7\n',
    "R4 return after a break in the body": H + '    for k in range(3):\n        if x[k] > 0:\n            break\n        return k\n    return 7\n',
    "R4 while True with a break before return": H + '    k = 0\n    while True:\n        if x[k] > 0:\n            break\n        return k\n    return 7\n',
    "R4 continue in an inner else": H + '    s = 0\n    for q in range(2):\n        for r in range(2):\n            s = s + 1\n        else:\n            if not c:\n                continue\n            s = s + 100\n        s = s + 10\n    return s\n',
    "R4 break in an inner else": H + '    s = 0\n    for q in range(3):\n        for r in range(2):\n            if x[r + q] > 4:\n                break\n        else:\n            break\n        s = s + 1\n    return s, q\n',
    "R4 name bound in else": H + '    for k in range(3):\n        if x[k] > 0:\n            break\n    else:\n        y = 5\n    return y\n',
    # R5: comprehension variables.
    "R5 comprehension shadows a name": H + '    k = 10\n    z = [k for k in range(3)]\n    return k, z[2]\n',
    "R5 generator in sum": H + '    k = 10\n    z = sum(k for k in range(3))\n    return k, z\n',
    "R5 comprehension over a possibly unbound name": H + '    for q in range(3):\n        if x[q] > 0:\n            break\n    s = sum([q for q in range(2)])\n    return s\n',
    # FR4 and the general case of records through branches.
    "FR4 plain arm and a skippable loop": H + '    if c:\n        b = x[5]\n    else:\n        for k in range(3):\n            if x[k] > 0:\n                break\n            b = x[4]\n    return b\n',
    "a break in an arm before its binding": H + '    for k in range(3):\n        if c:\n            if x[k] > 0:\n                break\n            b = 1\n        else:\n            b = 2\n    return b\n',
    "a break before an if that binds in both arms": H + '    for k in range(3):\n        if x[k] > 0:\n            break\n        if c:\n            b = 1\n        else:\n            b = 2\n    return b\n',
    "nested branches binding in all arms": H + '    if c:\n        b = 1\n    else:\n        if x[0] > 0:\n            b = 2\n        else:\n            b = 3\n    return b\n',
}


@pytest.mark.parametrize("name", list(MORE))
@pytest.mark.parametrize("x", range(len(INPUTS)))
@pytest.mark.parametrize("c", [False, True])
def test_more_cases_are_never_wrong(name, x, c):
    assert_never_wrong(MORE[name], INPUTS[x], c)


@pytest.mark.parametrize("name", ["R3 find the first negative", "R3 tuple target", "R4 return in else", "R5 comprehension shadows a name",
                                  "FR4 plain arm and a skippable loop", "nested branches binding in all arms", "R4 continue in an inner else"])
@pytest.mark.parametrize("c", [False, True])
def test_valid_inputs_keep_their_proof(name, c):
    try:
        numpy_outputs(MORE[name], X6, c)
    except Exception:  # noqa: BLE001
        pytest.skip("Python raises on this input")
    assert_all_backends_match_numpy(MORE[name], X6, c)


def test_fuzz_unbound_524_1435():
    # A `continue` in an inner loop's `else` block skipped the inner loop's
    # iteration instead of the outer one's (wrong output on d691e6cf).
    source = '''def kernel(x: Integer[Array, "6"], n: Integer, c: Boolean, d: Boolean):
    s = 0
    a = 1
    b = -1
    if x[5] > 5:
        a = n % 4
        a = 5
    else:
        for k in range(1, 3):
            for j in x[:2]:
                if x[1] > 3:
                    return b
                s = s + n % 4
                s = s + 1
            s = s + a
        y = n % 4
        for q in range(1, 3):
            for r in x[:2]:
                s = s + 2
                if c:
                    return b
                s = s + x[1]
            else:
                if not c:
                    continue
                y = s
                a = n % 4
            b = s
    return b
'''
    for c in (False, True):
        assert_never_wrong(source, np.arange(6, dtype=np.int64), 2, c, True)
        assert_all_backends_match_numpy(source, np.arange(6, dtype=np.int64), 2, c, True)
